const item = $input.first().json.body || $input.first().json;

const matchId = item.matchId || 1;
const sport = item.sport || 'CRICKET';
const tournamentName = item.tournamentName || 'Mana Community Championship';
const teamA = item.teamA || 'Team Alpha';
const teamB = item.teamB || 'Team Beta';
const scoreSummary = item.scoreSummary || {};
const topPerformers = item.topPerformers || [];
const matchResult = item.result || 'Match Completed';

const prompt = `You are the Official Sports Editor and Chief Analyst for the Mana Community Sports League.
A match has just concluded. Analyze the scorecard and generate a thrilling, high-energy match summary and badge awards.

Match Details:
- Sport: ${sport}
- Tournament: ${tournamentName}
- Teams: ${teamA} vs ${teamB}
- Result: ${matchResult}
- Scorecard / Stats:
${JSON.stringify(scoreSummary, null, 2)}
- Key Player Stats:
${JSON.stringify(topPerformers, null, 2)}

Respond ONLY with a valid JSON object matching this exact schema:
{
  "headline": "Punchy, exciting news headline (e.g. Titans Edge Strikers in Final-Ball Thriller)",
  "recap": "2-3 paragraph engaging narrative describing the match flow, momentum shifts, and dramatic finish",
  "keyMoments": [
    "Moment 1 with over/minute and player impact",
    "Moment 2",
    "Moment 3"
  ],
  "mvp": {
    "playerName": "string",
    "team": "string",
    "rationale": "Why this player won Player of the Match"
  },
  "badgeRecommendations": [
    {
      "playerName": "string",
      "badgeName": "CLUTCH_PERFORMER" | "CENTURY_MAKER" | "GOLDEN_BOOT" | "HAT_TRICK_HERO" | "UNSUNG_HERO" | "WALL_OF_DEFENSE",
      "reason": "Specific match stat that justifies this badge"
    }
  ],
  "socialBulletin": "Concise 3-bullet WhatsApp / Community Feed broadcast text with emojis ready to share"
}`;

return [{
  json: {
    matchId,
    sport,
    tournamentName,
    prompt
  }
}];

const geminiResponse = $input.first().json;
let parsedAnalysis = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsedAnalysis = JSON.parse(rawText);
} catch (err) {
  parsedAnalysis = {
    headline: "Match Concluded with High Drama",
    recap: "Both teams displayed exceptional sportsmanship in a tightly contested fixture.",
    keyMoments: ["Decisive plays in closing stages settled the outcome"],
    mvp: { playerName: "Outstanding Player", team: "Winning Team", rationale: "Consistent match-winning impact" },
    badgeRecommendations: [],
    socialBulletin: "🏆 Match completed! Check the leaderboard for updated standings."
  };
}

const matchMeta = $('Format Sports Prompt').first().json;

return [{
  json: {
    status: "success",
    matchId: matchMeta.matchId,
    sport: matchMeta.sport,
    tournamentName: matchMeta.tournamentName,
    generatedAt: new Date().toISOString(),
    data: parsedAnalysis
  }
}];
